    (2064, 2, 'džiovinti', ARRAY['']::text[], 'Dauguma kirčiuotų veiksmažodžių bendraties priesagų (-áuti, -ė́ti, -ýti, -óti, -úoti) žymimos dešininiu kirčio ženklu. Išimtis – kirčiuota veiksmažodžių priesaga„-ìnti“, kuri žymima kairiniu kirčio ženklu.', 'džiovìnti', 5, 'LEFT'),
