    (2067, 2, 'erkė', ARRAY['']::text[], 'Mišriųjų dvigarsių kirčiuotas pirmas dėmuo žymimas dešininiu (al, am, an, ar, el, em, en, er) arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'érkė', 0, 'RIGHT'),
