    (3132, 3, 'valgykloje', ARRAY['2 kirčiuotė']::text[], 'Antrosios kirčiuotės daiktavardžiai su dviskiemenėmis galūnėmis vienaskaitos įnagininko ir vietininko linksniuose kirčiuojami riestiniu kirčio ženklu (pvz., skaĩčiumi, skaĩčiuje)', 'valgỹkloje', 4, 'ACUTE'),
    (3133, 3, 'vadovu', ARRAY['2 kirčiuotė']::text[], '1. Antrosios ir ketvirtosios kirčiuočių vienaskaitos įnagininkas beveik visada kirčiuojamas galūnėje. Išimtis – antrosios kirčiuotės dviskiemenės galūnės (pvz., aliẽjumi). 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba riestiniu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojama galūnė (priešpaskutinio skiemens taisyklė). Pavyzdžiui, agùrką→ agurkù, agurkùs; knỹgą→ knygà, knygàs.', 'vadovù', 5, 'LEFT'),
    (3134, 3, 'vyšnias', ARRAY['2 kirčiuotė']::text[], '1. Antrosios ir ketvirtosios kirčiuočių daugiskaitos galininkas visada kirčiuojamas galūnėje. 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba riestiniu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojama galūnė (priešpaskutinio skiemens taisyklė). Pavyzdžiui, agùrką→ agurkù, agurkùs; knỹgą→ knygà, knygàs.', 'vyšniàs', 5, 'LEFT'),
    (3135, 3, 'žodžius', ARRAY['2 kirčiuotė']::text[], '1. Antrosios ir ketvirtosios kirčiuočių daugiskaitos galininkas visada kirčiuojamas galūnėje. 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba riestiniu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojama galūnė (priešpaskutinio skiemens taisyklė). Pavyzdžiui, agùrką→ agurkù, agurkùs; knỹgą→ knygà, knygàs.', 'žodžiùs', 5, 'LEFT'),
    (3136, 3, 'žirgus', ARRAY['3 kirčiuotė']::text[], '1. Pirmosios ir trečiosios kirčiuotės žodžiai daugiskaitos galininko linksnyje kirčiuojami antrame nuo galo skiemenyje kairiniu arba dešininiu kirčio ženklu. 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba dešininiu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojamas kamienas (priešpaskutinio skiemens taisyklė). Pavyzdžiui, kálną→ kálnu, kálnus; bùrną→ bùrna, bùrnas.', 'žìrgus', 1, 'LEFT'),
    (3137, 3, 'žmona', ARRAY['3 kirčiuotė, vns. įn.']::text[], '1. Pirmosios ir trečiosios kirčiuotės žodžiai daugiskaitos galininko linksnyje kirčiuojami antrame nuo galo skiemenyje kairiniu arba dešininiu kirčio ženklu. 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba dešininiu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojamas kamienas (priešpaskutinio skiemens taisyklė).', 'žmóna', 2, 'RIGHT'),
    (3138, 3, 'žiūrovus', ARRAY['2 kirčiuotė']::text[], '1. Antrosios ir ketvirtosios kirčiuočių daugiskaitos galininkas visada kirčiuojamas galūnėje. 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba riestiniu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojama galūnė (priešpaskutinio skiemens taisyklė). Pavyzdžiui, agùrką→ agurkù, agurkùs; knỹgą→ knygà, knygàs.', 'žiūrovùs', 6, 'LEFT'),
    (3139, 3, 'žvilgsniu', ARRAY['2 kirčiuotė']::text[], '1. Antrosios ir ketvirtosios kirčiuočių vienaskaitos įnagininkas beveik visada kirčiuojamas galūnėje. Išimtis – antrosios kirčiuotės dviskiemenės galūnės (pvz., aliẽjumi). 2. Kai kirčiuotas priešpaskutinis vienaskaitos galininko skiemuo ir jis yra žymimas kairiniu arba riestiniu kirčio ženklu, tai vienaskaitos įnagininko ir daugiskaitos galininko linksniuose visada kirčiuojama galūnė (priešpaskutinio skiemens taisyklė). Pavyzdžiui, agùrką→ agurkù, agurkùs; knỹgą→ knygà, knygàs.', 'žvilgsniù', 8, 'LEFT'),
    (3140, 3, 'lengviems', ARRAY['4 kirčiuotė']::text[], 'Daugumos linksniuojamų žodžių vienaskaitos ir daugiskaitos naudininkų kirčiuota galūnė žymima dešininiu kirčio ženklu. Išimtis: linksniuojami žodžiai su galūne „-ìms“ (pvz., akìms).', 'lengvíems', 5, 'RIGHT'),
    (3141, 3, 'stiprioms', ARRAY['4 kirčiuotė']::text[], 'Daugumos linksniuojamų žodžių vienaskaitos ir daugiskaitos naudininkų kirčiuota galūnė žymima dešininiu kirčio ženklu. Išimtis: linksniuojami žodžiai su galūne „-ìms“ (pvz., akìms).', 'stiprióms', 6, 'RIGHT'),
    (3142, 3, 'brangiausiais', ARRAY['1 kirčiuotė']::text[], '1. Pirmosios kirčiuotės žodžiai antrame nuo galo skiemenyje kirčiuojami kairiniu arba dešininiu kirčio ženklu. 2. Dvibalsių kirčiuotas pirmas dėmuo žymimas dešininiu (ai, au, ei, ie, uo) arba kairiniu (eu, oi, ou, ui) kirčio ženklu.', 'brangiáusiais', 6, 'RIGHT'),
    (3143, 3, 'drąsesnis', ARRAY['4 kirčiuotė']::text[], 'Aukštesniojo laipsnio būdvardžiai visada turi kirčiuotą priesagą „-èsn-“ ir yra ketvirtosios kirčiuotės.', 'drąsèsnis', 4, 'LEFT'),
    (3144, 3, 'malonu', ARRAY['bdv. bevardė g.']::text[], 'Bevardės giminės nelyginamojo laipsnio būdvardžiai išlaiko vyriškosios giminės būdvardžių vienaskaitos vardininko kirčio vietą ir kirčio ženklą.', 'malonù', 5, 'LEFT'),
    (3145, 3, 'brangu', ARRAY['bdv. bevardė g.']::text[], 'Bevardės giminės nelyginamojo laipsnio būdvardžiai išlaiko vyriškosios giminės būdvardžių vienaskaitos vardininko kirčio vietą ir kirčio ženklą.', 'brangù', 5, 'LEFT'),
    (3146, 3, 'tobulas', ARRAY['3<sup>a</sup> kirčiuotė']::text[], '3a kirčiuotės žodžiai, jei kirčiuojami kamiene, turi dešininį kirčio ženklą trečiame nuo galo skiemenyje.', 'tóbulas', 1, 'RIGHT'),
    (3147, 3, 'artimą', ARRAY['3<sup>b</sup> kirčiuotė']::text[], '3b kirčiuotės žodžiai, jei kirčiuojami kamiene, turi riestinį arba kairinį kirčio ženklą trečiame nuo galo skiemenyje.', 'ar̃timą', 1, 'ACUTE'),
    (3148, 3, 'voverė', ARRAY['3<sup>a</sup> kirčiuotė']::text[], '1.Trečiosios ir ketvirtosios kirčiuočių daiktavardžiai, vienaskaitos vardininke turintys galūnę „-ė“, visada kirčiuojami galūnėje. 2. Ilgasis kirčiuotas žodžio galo skiemuo dažniausiai žymimas riestiniu kirčio ženklu.', 'voverė̃', 5, 'ACUTE'),
    (3149, 3, 'pajūris', ARRAY['1 kirčiuotė']::text[], 'Pirmosios kirčiuotės žodžiai antrame nuo galo skiemenyje kirčiuojami kairiniu arba dešininiu kirčio ženklu.', 'pajū́ris', 3, 'RIGHT'),
    (3150, 3, 'klausytojas', ARRAY['1 kirčiuotė']::text[], '1.Trečias ir tolimesni nuo galo skiemenys kirčiuojami pagal tarimą arba tikrinami pagal pamatinį žodį (klausyti). 2. Dauguma kirčiuotų veiksmažodžių bendraties priesagų (-áuti, -ė́ti, -ýti, -óti, -úoti) žymimos dešininiu kirčio ženklu. Išimtis – kirčiuota veiksmažodžių priesaga „-ìnti“  kuri žymima kairiniu kirčio ženklu.', 'klausýtojas', 5, 'RIGHT'),
    (4001, 4, 'draugiškasis', ARRAY['']::text[], 'Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių.', 'draũgiškasis', 3, 'ACUTE'),
    (4002, 4, 'išmintingasis', ARRAY['']::text[], '1. Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Kirčiuota būdvardžių priesaga „-ing-“ visada žymima kairiniu kirčio ženklu ir yra pirmosios kirčiuotės.', 'išmintìngasis', 6, 'LEFT'),
    (4003, 4, 'galingųjų', ARRAY['']::text[], '1. Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Kirčiuota būdvardžių priesaga „-ing-“ visada žymima kairiniu kirčio ženklu ir yra pirmosios kirčiuotės.', 'galìngųjų', 3, 'LEFT'),
    (4004, 4, 'garbinguoju', ARRAY['']::text[], '1. Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Kirčiuota būdvardžių priesaga „-ing-“ visada žymima kairiniu kirčio ženklu ir yra pirmosios kirčiuotės.', 'garbìnguoju', 4, 'LEFT'),
    (4005, 4, 'atsakingasis', ARRAY['']::text[], '1. Pastovią kirčio vietą turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Kirčiuota būdvardžių priesaga „-ing-“ visada žymima kairiniu kirčio ženklu ir yra pirmosios kirčiuotės.', 'atsakìngasis', 5, 'LEFT'),
    (4006, 4, 'broliškajam', ARRAY['']::text[], '1. Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Pamatinis žodis „brolis“ yra pirmosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas dešininiu kirčio ženklu.', 'bróliškajam', 2, 'RIGHT'),
    (4007, 4, 'dieviškajam', ARRAY['']::text[], '1. Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Pamatinis žodis „dievas“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas riestiniu kirčio ženklu.', 'diẽviškajam', 2, 'ACUTE'),
    (4008, 4, 'kalnuotasis', ARRAY['']::text[], '1. Pastovią kirčio vietą žodžio kamiene turi įvardžiuotiniai būdvardžiai, padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 2. Būdvardis „kalnuotas“ yra pirmosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas dešininiu kirčio ženklu.', 'kalnúotasis', 4, 'RIGHT'),
    (4009, 4, 'nuostabioji', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, kirčiuojami galūnėje. Vyr. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami kairiniu kirčio ženklu (nuostabùsis, baltàsis), o mot. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami dešininiu kirčio ženklu (nuostabióji, baltóji).', 'nuostabióji', 8, 'RIGHT'),
    (4010, 4, 'gerosios', ARRAY['vns. kilm.']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. kilm. l. kirčiuojami galūnėje riestiniu kirčio ženklu (gerõsios), o vyr. g. vns. kilm. l. kirčiuojamas kamiene, kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės (gẽrojo).', 'gerõsios', 3, 'ACUTE'),
    (4011, 4, 'gražiajai', ARRAY['']::text[], '1. Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. naud. l. kirčiuojami kamiene (kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės), o vyr. g. vns. naud. l. kirčiuojami galūnėje dešininiu kirčio ženklu (gražiájam). 2. Būdvardis ,,graži“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas riestiniu kirčio ženklu. 3. Ilgieji kirčiuoti balsiai „a, e“ visada žymimi riestiniu kirčio ženklu.', 'grãžiajai', 2, 'ACUTE'),
    (4012, 4, 'didžiojoje', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, vyr. g. ir mot. g.  vns. ir dgs. viet. l. kirčiuojami galūnėje riestiniu kirčio ženklu (didžiãjame, didžiõjoje, didžiuõsiuose, didžiõsiose).', 'didžiõjoje', 5, 'ACUTE'),
    (4013, 4, 'artimųjų', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. dgs. kilm. l. kirčiuojami galūnėje riestiniu kirčio ženklu.', 'artimų̃jų', 5, 'ACUTE'),
    (4014, 4, 'mažosioms', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. dgs. naud. l. kirčiuojami galūnėje dešininiu kirčio ženklu (mažíesiems, mažósioms).', 'mažósioms', 3, 'RIGHT'),
    (4015, 4, 'baltąsias', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. dgs. gal. l. kirčiuojami galūnėje dešininiu kirčio ženklu (baltúosius, baltą́sias).', 'baltą́sias', 4, 'RIGHT'),
    (4016, 4, 'sunkiosiomis', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. dgs. įn. l. kirčiuojami galūnėje riestiniu kirčio ženklu (sunkiaĩsiais, sunkiõsiomis).', 'sunkiõsiomis', 5, 'ACUTE'),
    (4017, 4, 'lengvąją', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. vns. gal. l. kirčiuojami kamiene. Kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės. 2. Būdvardis ,,lengva“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas riestiniu kirčio ženklu.', 'leñgvąją', 2, 'ACUTE'),
    (4018, 4, 'mieluoju', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. vns. gal. l. kirčiuojami galūnėje (mielúoju, mielą́ja).', 'mielúoju', 4, 'RIGHT'),
    (4019, 4, 'šaltoji', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, kirčiuojami galūnėje. Vyr. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami kairiniu kirčio ženklu (nuostabùsis, baltàsis), o mot. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami dešininiu kirčio ženklu (nuostabióji, baltóji).', 'šaltóji', 4, 'RIGHT'),
    (4020, 4, 'mandagioji', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, kirčiuojami galūnėje. Vyr. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami kairiniu kirčio ženklu (nuostabùsis, baltàsis), o mot. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami dešininiu kirčio ženklu (nuostabióji, baltóji).', 'mandagióji', 7, 'RIGHT'),
    (4021, 4, 'sumaniojo', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. kilm. l. kirčiuojami galūnėje riestiniu kirčio ženklu (gerõsios), o vyr. g. vns. kilm. l. kirčiuojamas kamiene, kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės (gẽrojo).', 'sumãniojo', 3, 'ACUTE'),
    (4022, 4, 'aštriosios', ARRAY['vns. kilm.']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. kilm. l. kirčiuojami galūnėje riestiniu kirčio ženklu (gerõsios), o vyr. g. vns. kilm. l. kirčiuojamas kamiene, kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės (gẽrojo).', 'aštriõsios', 5, 'ACUTE'),
    (4023, 4, 'maloniajam', ARRAY['']::text[], 'Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. naud. l. kirčiuojami kamiene (kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės), o vyr. g. vns. naud. l. kirčiuojami galūnėje dešininiu kirčio ženklu (gražiájam).', 'maloniájam', 6, 'RIGHT'),
    (4024, 4, 'ramiajai', ARRAY['']::text[], '1. Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. naud. l. kirčiuojami kamiene (kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės), o vyr. g. vns. naud. l. kirčiuojami galūnėje dešininiu kirčio ženklu (gražiájam). 2. Būdvardis ,,rami“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas riestiniu kirčio ženklu. 3. Ilgieji kirčiuoti balsiai „a, e“ visada žymimi riestiniu kirčio ženklu.', 'rãmiajai', 1, 'ACUTE'),
    (4025, 4, 'drąsiajai', ARRAY['']::text[], '1. Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. naud. l. kirčiuojami kamiene (kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės), o vyr. g. vns. naud. l. kirčiuojami galūnėje dešininiu kirčio ženklu (gražiájam). 2. Būdvardis ,,drąsi“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas riestiniu kirčio ženklu.', 'drą̃siajai', 2, 'ACUTE'),
    (4026, 4, 'žiląją', ARRAY['']::text[], '1. Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, ir vyr. g., ir mot. g. vns. gal. l. kirčiuojami kamiene. Kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės. 2. Būdvardis ,,žila“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo trumpasis skiemuo žymimas kairiniu kirčio ženklu.', 'žìląją', 1, 'LEFT'),
