    (4068, 4, 'aštuonis', ARRAY['']::text[], '1. Skaitvardžiai ,,septyni, aštuoni, devyni“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai. 2. Trečiosios kirčiuotės daugiskaitos galininko linksnis kirčiuojamas kamiene. 3. Trečiosios kirčiuotės kirčiuotas antras nuo galo skiemuo kirčiuojamas dešininiu arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'aštúonis', 3, 'RIGHT'),
    (4069, 4, 'devynis', ARRAY['']::text[], '1. Skaitvardžiai ,,septyni, aštuoni, devyni“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai. 2. Trečiosios kirčiuotės daugiskaitos galininko linksnis kirčiuojamas kamiene. 3. Trečiosios kirčiuotės kirčiuotas antras nuo galo skiemuo kirčiuojamas dešininiu arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'devýnis', 3, 'RIGHT'),
    (4070, 4, 'pirmu', ARRAY['']::text[], '1. Skaitvardžiai „vienas, viena, pirmas, pirma“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai ,,baltas, balta“. 2. Trečiosios kirčiuotės būdvardžių vienaskaitos įnagininko linksnis paprastai kirčiuojamas kamiene. 3. Trečiosios kirčiuotės antras nuo galo kirčiuotas ilgasis skiemuo kirčiuojamas dešininiu arba kairiniu kirčio ženklu. 4. Mišriųjų dvigarsių kirčiuotas pirmas dėmuo žymimas dešininiu (al, am, an, ar, el, em, en, er) arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'pìrmu', 1, 'LEFT'),
    (4071, 4, 'pirma', ARRAY['vns. įn. l.']::text[], '1. Skaitvardžiai „vienas, viena, pirmas, pirma“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai ,,baltas, balta“. 2. Trečiosios kirčiuotės antras nuo galo kirčiuotas ilgasis skiemuo kirčiuojamas dešininiu arba kairiniu kirčio ženklu. 3. Trečiosios kirčiuotės būdvardžių vienaskaitos įnagininko linksnis paprastai kirčiuojamas kamiene. 4. Mišriųjų dvigarsių kirčiuotas pirmas dėmuo žymimas dešininiu (al, am, an, ar, el, em, en, er) arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'pìrma', 1, 'LEFT'),
    (4072, 4, 'pirma', ARRAY['vns. vard l.']::text[], '1. Skaitvardžiai „vienas, viena, pirmas, pirma“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai ,,baltas, balta“. 2. Trečiosios kirčiuotės mot. g. būdvardžių su galūne „-a“ vienaskaitos vardininko linksnis kirčiuojamas galūnėje (baltà).', 'pirmà', 4, 'LEFT'),
    (4073, 4, 'pirmus', ARRAY['']::text[], '1. Skaitvardžiai „vienas, viena, pirmas, pirma“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai ,,baltas, balta“. 2. Trečiosios kirčiuotės antras nuo galo kirčiuotas ilgasis skiemuo kirčiuojamas dešininiu arba kairiniu kirčio ženklu. 3. Visų kalbos dalių ir visų kirčiuočių vienaskaitos galininko linksnis kirčiuojamas kamiene. 4. Mišriųjų dvigarsių kirčiuotas pirmas dėmuo žymimas dešininiu (al, am, an, ar, el, em, en, er) arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'pìrmus', 1, 'LEFT'),
    (4074, 4, 'pirmas', ARRAY['dgs. gal. l.']::text[], '1. Skaitvardžiai „vienas, viena, pirmas, pirma“ kirčiuojami kaip trečiosios kirčiuotės būdvardžiai ,,baltas, balta“. 2. Trečiosios kirčiuotės antras nuo galo kirčiuotas ilgasis skiemuo kirčiuojamas dešininiu arba kairiniu kirčio ženklu. 3. Visų kalbos dalių ir visų kirčiuočių vienaskaitos galininko linksnis kirčiuojamas kamiene. 4. Mišriųjų dvigarsių kirčiuotas pirmas dėmuo žymimas dešininiu (al, am, an, ar, el, em, en, er) arba kairiniu (il, im, in, ir, ul, um, un, ur) kirčio ženklu.', 'pìrmas', 1, 'LEFT'),
    (4075, 4, 'penkioliktąjį', ARRAY['']::text[], '1. Įvardžiuotiniai skaitvardžiai kirčiuojami kaip įvardžiuotiniai būdvardžiai. 2. Įvardžiuotinių būdvardžių pastovią kirčio vietą žodžio kamiene turi tie įvardžiuotiniai būdvardžiai, kurie yra padaryti iš pirmosios kirčiuotės daugiaskiemenių būdvardžių. 3. Skaitvardžiai nuo vienuolikos iki devyniolikos kirčiuojami pirmąja kirčiuote ir turi tvirtapradę priegaidę.', 'penkióliktąjį', 5, 'RIGHT'),
    (4076, 4, 'pirmoji', ARRAY['']::text[], '1. Įvardžiuotiniai skaitvardžiai kirčiuojami kaip įvardžiuotiniai būdvardžiai. 2. Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, kirčiuojami galūnėje. Vyr. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami kairiniu kirčio ženklu (nuostabùsis, baltàsis), o mot. g. vns. vard. įvardžiuotiniai  būdvardžiai kirčiuojami dešininiu kirčio ženklu (nuostabióji, baltóji).', 'pirmóji', 4, 'RIGHT'),
    (4077, 4, 'antrajai', ARRAY['']::text[], '1. Įvardžiuotiniai skaitvardžiai kirčiuojami kaip įvardžiuotiniai būdvardžiai. 2. Įvardžiuotiniai būdvardžiai, padaryti iš antrosios, trečiosios ar ketvirtosios kirčiuotės pamatinio žodžio, mot. g. vns. naud. l. kirčiuojami kamiene (kirčio ženklas priklauso nuo pamatinio žodžio kirčiuotės), o vyr. g. vns. naud. l. kirčiuojami galūnėje dešininiu kirčio ženklu (gražiájam). 3. Skaitvardis ,,antra“ yra ketvirtosios kirčiuotės, tad kirčiuotas antras nuo galo ilgasis skiemuo žymimas riestiniu kirčio ženklu.', 'añtrajai', 1, 'ACUTE'),
