    (5071, 5, 'rašydavau', ARRAY['']::text[], '1. Dauguma išvestinių veiksmažodžių formų, padarytų iš bendraties, išlaiko veiksmažodžio bendraties kirčio vietą ir kirčio ženklą. 2. Dauguma kirčiuotų veiksmažodžių bendraties priesagų (-áuti, -ė́ti, -ýti, -óti, -úoti) žymimos dešininiu kirčio ženklu. Išimtis – kirčiuota veiksmažodžių priesaga „-ìnti“, kuri žymima kairiniu kirčio ženklu.', 'rašýdavau', 3, 'RIGHT'),
    (5072, 5, 'kalbėtų', ARRAY['']::text[], '1. Dauguma išvestinių veiksmažodžių formų, padarytų iš bendraties, išlaiko veiksmažodžio bendraties kirčio vietą ir kirčio ženklą. 2. Dauguma kirčiuotų veiksmažodžių bendraties priesagų (-áuti, -ė́ti, -ýti, -óti, -úoti) žymimos dešininiu kirčio ženklu. Išimtis – kirčiuota veiksmažodžių priesaga „-ìnti“, kuri žymima kairiniu kirčio ženklu.', 'kalbė́tų', 4, 'RIGHT'),
    (5073, 5, 'skaitys', ARRAY['']::text[], 'Jei veiksmažodžio bendratis priešpaskutiniame skiemenyje turi tvirtapradę priegaidę, tai būsimojo laiko 3 asmenyje ji virs tvirtagale. Jei būsimojo laiko 3 a. balsis sutrumpėja, jis kirčiuojamas trumpai.', 'skaitỹs', 5, 'ACUTE'),
    (5074, 5, 'džius', ARRAY['']::text[], 'Jei veiksmažodžio bendratis priešpaskutiniame skiemenyje turi tvirtapradę priegaidę, tai būsimojo laiko 3 asmenyje ji virs tvirtagale. Jei būsimojo laiko 3 a. balsis sutrumpėja, jis kirčiuojamas trumpai.', 'džiùs', 3, 'LEFT'),
    (5075, 5, 'šoka', ARRAY['']::text[], '1. Jei asmenuojant esamojo laiko dviskiemenius veiksmažodžius kirčio vieta nesikeičia, tai visos es. l. formos kirčiuojamos tvirtapradiškai (šóku, šóki – šóka). 2. Taisyklę galima taikyti ir atvirkščiai: jei es. l. 3 a. dviskiemenis veiksmažodis kirčiuojamas tvirtapradiškai, tai es. l. 1 ir 2 asmenyse kirčiuojame toje pačioje vietoje ir tuo pačiu kirčio ženklu.', 'šóka', 1, 'RIGHT'),
    (5076, 5, 'Vilnius', ARRAY['1 kirčiuotė']::text[], 'Pirmosios kirčiuotės žodžiai antrame nuo galo skiemenyje kirčiuojami kairiniu (il, im, in, ir, ul, um, un, ur) arba dešininiu kirčio ženklu.', 'Vìlnius', 1, 'LEFT'),
    (5077, 5, 'Baltupiai', ARRAY['1 kirčiuotė']::text[], '1. Trečias ir tolimesni nuo galo skiemenys kirčiuojami pagal pagrindinius kirčiavimo dėsnius arba išlaiko pamatinio žodžio priegaidę ir kirčio ženklą. 2. Žodžio trečias nuo galo skiemuo išlaiko pamatinio žodžio „báltas“ tvirtapradę priegaidę ir kirčio ženklą.', 'Báltupiai', 1, 'RIGHT'),
    (5078, 5, 'Justiniškės', ARRAY['1 kirčiuotė']::text[], '1. Trečias ir tolimesni nuo galo skiemenys kirčiuojami pagal pagrindinius kirčiavimo dėsnius arba išlaiko pamatinio žodžio priegaidę ir kirčio ženklą. 2. Žodžio trečias nuo galo skiemuo yra trumpasis, todėl kirčiuojamas kairiniu kirčio ženklu.', 'Justìniškės', 4, 'LEFT'),
    (5079, 5, 'Justiniškių', ARRAY['1 kirčiuotė']::text[], '1. Trečias ir tolimesni nuo galo skiemenys kirčiuojami pagal pagrindinius kirčiavimo dėsnius arba išlaiko pamatinio žodžio priegaidę ir kirčio ženklą. 2. Pirmosios kirčiuotės žodžiai visuose linksniuose kirčiuojami pastoviai kamiene. 3. Žodžio trečias nuo galo skiemuo yra trumpasis, todėl kirčiuojamas kairiniu kirčio ženklu.', 'Justìniškių', 4, 'LEFT'),
