-- Seed accentuation: 600 entries, including repeated word texts.
-- Safe to rerun: existing IDs are skipped, no updates/deletes.
-- Run after EF migrations.
BEGIN;

ON CONFLICT ("Id") DO NOTHING;

-- Keep the sequence aligned for later auto-generated IDs.
SELECT setval(pg_get_serial_sequence('"AccentuationEntries"', 'Id'), (SELECT MAX("Id") FROM "AccentuationEntries"), true);

COMMIT;

SELECT COUNT(*) AS accentuation_count FROM public."AccentuationEntries";
